                ),
                "mensaje": (
                    "El usuario autenticado "
                    "no contiene una identidad "
                    "de email válida"
                ),
            },
        )

    return email


def _translate_error(
    exc: Exception,
) -> None:
    if isinstance(
        exc,
        service.SessionNotFoundError,
    ):
        raise HTTPException(
            status_code=404,
            detail="Sesión no encontrada",
        ) from exc

    if isinstance(
        exc,
        repository.SchemaNotReadyError,
    ):
        raise HTTPException(
            status_code=503,
            detail=(
                "El esquema SQL "
                "del Asistente IA "
                "no está disponible"
            ),
        ) from exc

    if isinstance(
        exc,
        service.LLMTimeoutError,
    ):
        raise HTTPException(
            status_code=504,
            detail=(
                "El proveedor IA excedió "
                "el tiempo límite"
            ),
        ) from exc

    if isinstance(
        exc,
        service.LLMProviderError,
    ):
        raise HTTPException(
            status_code=503,
            detail=(
                "El proveedor IA "
                "no está disponible"
            ),
        ) from exc

    if isinstance(
        exc,
        ValueError,
    ):
        raise HTTPException(
            status_code=422,
            detail=str(exc),
        ) from exc

    raise exc


